shell_commands:
mkdir -p /tmp/probe-ws && cat > /tmp/probe-ws/probe.mjs <<'EOF'
import {WebSocketServer, WebSocket} from '/var/tmp/loop-bench/runs/48a55d0b7499/workspace/target/node_modules/ws/wrapper.mjs';

const wss = new WebSocketServer({noServer: true, port: 0});
wss.on('connection', ws => {
  ws.on('message', raw => {
    const frame = JSON.parse(String(raw));
    if (frame.type === 'list') {
      // mimic handleListSessions: an await over a sync store call
      Promise.resolve().then(async () => {
        await storeList();
        ws.send(JSON.stringify({type: 'session_list'}));
      });
    } else if (frame.type === 'ping') {
      ws.send(JSON.stringify({type: 'pong'}));
    }
  });
});
const storeList = () => [];

const run = async () => {
  await new Promise(r => wss.on('listening', r));
  const port = wss.address().port;
  for (let i = 0; i < 5; i++) {
    const order = await new Promise(resolve => {
      const ws = new WebSocket(`ws://127.0.0.1:${port}`);
      const seen = [];
      ws.on('open', () => {
        ws.send(JSON.stringify({type: 'list'}));
        ws.send(JSON.stringify({type: 'ping', timestamp: 1}));
      });
      ws.on('message', raw => {
        const f = JSON.parse(String(raw));
        if (f.type === 'pong') { resolve(seen.join(',')); ws.close(); }
        else seen.push(f.type);
      });
    });
    console.log(`run ${i}: frames-before-pong = [${order}]`);
  }
  wss.close();
};
run();
EOF
cd /tmp/probe-ws && timeout 60 node probe.mjs

cd /var/tmp/loop-bench/runs/48a55d0b7499/workspace/target && for f in specs/hal-engine-abandon-on-close/spec.md specs/hal-engine-tool-executor-throw/spec.md specs/hal-engine-websocket-protocol/spec.md; do
  perl -i -pe 's/messageHandler\.test\.ts#L(773|789|806|823|841|854|874|884|890)\b/"messageHandler.test.ts#L".($1+12)/e' "$f";
done && grep -rn "messageHandler.test.ts#L" specs/ | grep -oE '#L[0-9]+' | sort -t L -k2 -n | uniq -c | tail -12
